where id='aa369f75-e047-535c-a433-9c5d8dcf9366';

-- month-freedom-02
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-02-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Я надеюсь, что, пройдя первый урок, вы чётко сформулировали намерение на месяц, составили для себя план практик на каждый день, и уже приступили к их выполнению. А значит, вы готовы к первой глубокой исцеляющей практике.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть второй урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='a0566599-ab24-505c-a3e1-90ff1043e248';

-- month-freedom-03
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 3</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-03-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Движемся дальше в направлении гармоничного проявления состояний пятой чакры и здоровья органов, психосоматически с ней связанных.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть третий урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Урок 3</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='4281828a-d19b-5848-8dd7-607607f55404';

-- month-freedom-04
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-04-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Сюрприз! Чтобы поддержать вас в пространстве свободы и творчества, предлагаю вам дополнительный видеоурок с практикой, направленной на гармонизацию пятой чакры.</p><p></p><p>Это один из уроков, которые я проводил по утрам в прямом эфире, каждый раз выбирая направление в соответствии с планетными ритмами и особыми датами. Так как сейчас вы будете практиковать по записи, синхронности с теми энергиями уже нет. Однако, если вы настроитесь на волну урока, то возникнет резонанс, и практика принесёт вам наилучшие результаты.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Открыть доп. урок 1</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='9e2c1f73-6c32-5c59-b5cc-7a1d709d5186';

-- month-freedom-05
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 4</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-05-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Уже прошли три недели программы Месяца свободы. Пора появиться результатам практик. Если вы выполняете наши совместные практики, а также ежедневно практикуете самостоятельно (в соответствии с намерением, сформулированным на первом уроке), результаты уже должны проявиться! Если вы их не замечаете, обязательно поднимите этот вопрос на ближайшем вебинаре.</p><p></p><p>И сейчас перейдите к четвертому уроку. Сразу предупрежу - он длиннее обычного - целых три часа. И важно не прерываться в процессе практики, чтобы не потерять энергетическую нить. Поэтому выберите для этой практики момент, когда у вас будут три часа свободного времени. А также выберите такое место, где вы не будете стесняться прокричаться (и соседей не испугаете). А также приготовьте стаканчик воды, он не помешает. Урок очень плотный. Сначала мы выполним асаны, а затем будем практиковать с энергией букв.</p><p></p><p>Нажмите кнопку ниже, чтобы открыть четвёртый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Урок 4</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='f1cd2c64-4f9b-5def-804e-f9d4110da98a';

-- month-freedom-06
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-06-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Высылаю ещё один дополнительный урок, направленный на гармонизацию пятой чакры. Просто, немного другие техники, другие состояния (энергии), другое время...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть дополнительную практику в браузере, или посмотрите её в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Открыть доп. урок 2</a></p><p></p><p>До встречи на коврике!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='a6d2a486-d9eb-533f-80e0-b4698044265e';

-- month-freedom-07
update public.email_automation_steps set
  html_body='<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href="https://zamkovoi.yoga/m6/">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>',
  html_body_i18n=jsonb_set(html_body_i18n,'{ru}',to_jsonb('<div style="margin:0px 0 24px;text-align:center;"><img src="https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png" alt="Месяц свободы" width="504" height="146" style="width:100%;max-width:100%;height:auto;display:inline-block;border:0;" /></div><p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly">Урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href="https://zamkovoi.yoga/m6/">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>'::text)),
  blocks_i18n=jsonb_set(blocks_i18n,'{ru}','[{"id":"course-month-freedom-header","type":"image","src":"https://harmonizer.zamkovoi.yoga/email-cdn/email-assets/courses/month-freedom/m5_email-9b2159e146d3.png","alt":"Месяц свободы","width":"100%","align":"center","marginTop":0,"marginBottom":24,"naturalWidth":530,"naturalHeight":154},{"id":"month-freedom-07-text","type":"text","html":"<p>Здравствуйте, {{name}}!</p><p></p><p>Пришло время заключительного урока месяца практик, направленных на гармонизацию вишудхи. Я надеюсь, вы замечаете результаты выполняемых практик - как на уровне здоровья, так и в виде изменений в жизни, в вашем поведении, в восприятии окружающего вас мира (а может быть вы и в самом деле осознали, что сами создаёте мир, в котором живёте). Закрепитесь на достигнутом, и пойдите ещё дальше в результате практики пятого урока. Она о волшебстве...</p><p></p><p>Нажмите кнопку ниже, чтобы открыть пятый урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style=\"text-align:center\"><a href=\"{{course_lesson_url}}\" target=\"_blank\" style=\"border-style:solid;border-color:#6E9ECF;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#6E9ECF;mso-line-height-rule:exactly\">Урок 5</a></p><p></p><p>И я приглашаю вас в дальнейший путь. За месяц вы очистили и гармонизировали вишудху настолько, насколько это возможно в данное время. И это хороший фундамент для того, чтобы перейти на уровень шестой чакры - аджны (чакры мудрости), и проработать её сферы. Продолжайте движение вперёд, присоединяйтесь к практикам Месяца мудрости. Чтобы ознакомиться с описанием этого практикума, перейдите на страницу - <a href=\"https://zamkovoi.yoga/m6/\">https://zamkovoi.yoga/m6/</a></p><p></p><p>Всех благ!<br>Сергей Замковой</p>","align":"left","fontFamily":"system","fontSize":"md","marginTop":0,"marginBottom":0}]'::jsonb)
where id='de955c05-5bff-5e5c-995c-e4dfec7f169b';
